// The app's density stamp, moved out of index.html so the guest CSP needs no inline script. (Generated by scripts/build-join-site-app.js.)
(function () {
        // Storage can throw (site data blocked, some embedded webviews): the density stamp must
        // never take the page down with it.
        var read = function (key, fallback) {
          try {
            return localStorage.getItem(key) || fallback;
          } catch (_) {
            return fallback;
          }
        };
        var density = read("flowjoe_density", "compact");
        if (density === "compact" || density === "dense") document.body.classList.add("density-" + density);
        var surfaceStyle = read("flowjoe_surface_style", "filled");
        if (surfaceStyle === "filled") document.body.classList.add("shape-soft");
      })();
